<?php
$title='Content';require __DIR__.'/inc/header.php';$type=(string)get('type','articles');if(!in_array($type,['gadgets','jersey','fashion','articles','docs','pages'],true))$type='articles';$pdo=db();$message='';
$cats=$pdo->prepare("SELECT id,name FROM categories WHERE type IN (?, 'articles','docs','pages') AND status=1 ORDER BY name");$cats->execute([$type]);$cats=$cats->fetchAll();
$tags=$pdo->prepare("SELECT id,name FROM terms WHERE taxonomy='tag' AND post_type=? AND status=1 ORDER BY name");$tags->execute([$type]);$tags=$tags->fetchAll();
if(is_post()){verify_csrf();$action=(string)post('action','');
 if($action==='save'){ $id=(int)post('id',0);$titleX=trim((string)post('title'));$slug=slugify((string)post('slug',$titleX));$excerpt=trim((string)post('excerpt'));$content=(string)post('content');$status=(string)post('status','draft');$visibility=(string)post('visibility','public');$cat=(int)post('category_id',0)?:null;$seoT=trim((string)post('seo_title'));$seoD=trim((string)post('seo_description'));$seoK=trim((string)post('seo_keywords'));$schema=(string)post('schema_type','Article');$featured=post('featured')?1:0;$cover='';
   if(!empty($_FILES['cover_file']['name'])){try{$u=save_public_upload($_FILES['cover_file'],['jpg','jpeg','png','webp','gif','svg'],12000000,'content');$cover=$u['path'];}catch(Throwable $e){$message=$e->getMessage();}}
   if(!$cover)$cover=(string)post('existing_cover','');
   try{if($id){$pdo->prepare('UPDATE content_posts SET title=?,slug=?,excerpt=?,content=?,status=?,visibility=?,category_id=?,cover_image=?,seo_title=?,seo_description=?,seo_keywords=?,schema_type=?,featured=?,updated_at=CURRENT_TIMESTAMP WHERE id=? AND post_type=?')->execute([$titleX,$slug,$excerpt,$content,$status,$visibility,$cat,$cover,$seoT,$seoD,$seoK,$schema,$featured,$id,$type]);$postId=$id;}else{$pdo->prepare('INSERT INTO content_posts(post_type,title,slug,excerpt,content,status,visibility,category_id,cover_image,seo_title,seo_description,seo_keywords,schema_type,featured,author_id,published_at) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)')->execute([$type,$titleX,$slug,$excerpt,$content,$status,$visibility,$cat,$cover,$seoT,$seoD,$seoK,$schema,$featured,user()['id']??null,$status==='publish'?date('Y-m-d H:i:s'):null]);$postId=(int)$pdo->lastInsertId();}$pdo->prepare('DELETE FROM post_terms WHERE post_id=?')->execute([$postId]);foreach((array)post('tags',[]) as $tid)$pdo->prepare('INSERT OR IGNORE INTO post_terms(post_id,term_id) VALUES(?,?)')->execute([$postId,(int)$tid]);flash('success',($id?'Updated':'Created').' '.post_type_label($type).'.');redirect('/admin/content.php?type='.$type.'&edit='.$postId.'#editor');}catch(Throwable $e){$message=$e->getMessage();}
 }
 if($action==='bulk'){$ids=array_values(array_filter(array_map('intval',(array)post('ids',[]))));$bulk=(string)post('bulk_action','');if($ids){$ph=implode(',',array_fill(0,count($ids),'?'));
   if($bulk==='delete'){$pdo->prepare("DELETE FROM content_posts WHERE post_type=? AND id IN ($ph)")->execute([$type,...$ids]);flash('success','Selected posts deleted.');}
   elseif(in_array($bulk,['publish','draft','private'],true)){$pdo->prepare("UPDATE content_posts SET status=? WHERE post_type=? AND id IN ($ph)")->execute([$bulk,$type,...$ids]);flash('success','Status updated.');}
   elseif($bulk==='category:clear'){$pdo->prepare("UPDATE content_posts SET category_id=NULL WHERE post_type=? AND id IN ($ph)")->execute([$type,...$ids]);flash('success','Categories removed from selected posts.');}
   elseif(str_starts_with($bulk,'category:assign:')){$cid=(int)substr($bulk,16);$pdo->prepare("UPDATE content_posts SET category_id=? WHERE post_type=? AND id IN ($ph)")->execute([$cid,$type,...$ids]);flash('success','Category assigned.');}
   elseif(str_starts_with($bulk,'tag:add:')){$tid=(int)substr($bulk,8);foreach($ids as $pid)$pdo->prepare('INSERT OR IGNORE INTO post_terms(post_id,term_id) VALUES(?,?)')->execute([$pid,$tid]);flash('success','Tag assigned to selected posts.');}
   elseif(str_starts_with($bulk,'tag:remove:')){$tid=(int)substr($bulk,11);foreach($ids as $pid)$pdo->prepare('DELETE FROM post_terms WHERE post_id=? AND term_id=?')->execute([$pid,$tid]);flash('success','Tag removed from selected posts.');}
   elseif($bulk==='tags:clear'){foreach($ids as $pid)$pdo->prepare('DELETE FROM post_terms WHERE post_id=?')->execute([$pid]);flash('success','All tags removed from selected posts.');}
  }redirect('/admin/content.php?type='.$type);}
}
$editId=(int)get('edit',0);if($editId){redirect('/admin/content-edit.php?type='.$type.'&id='.$editId);} $edit=null;if(false){$st=$pdo->prepare('SELECT * FROM content_posts WHERE id=? AND post_type=?');$st->execute([$editId,$type]);$edit=$st->fetch();}
$form=$edit?:['id'=>0,'title'=>'','slug'=>'','excerpt'=>'','content'=>'','status'=>'draft','visibility'=>'public','category_id'=>'','cover_image'=>'','seo_title'=>'','seo_description'=>'','seo_keywords'=>'','schema_type'=>'Article','featured'=>0];
$posts=$pdo->prepare("SELECT p.*,c.name category_name FROM content_posts p LEFT JOIN categories c ON c.id=p.category_id WHERE p.post_type=? ORDER BY p.id DESC");$posts->execute([$type]);$posts=$posts->fetchAll();
$selectedTags=[];if($edit){$st=$pdo->prepare('SELECT term_id FROM post_terms WHERE post_id=?');$st->execute([$edit['id']]);$selectedTags=array_map('intval',$st->fetchAll(PDO::FETCH_COLUMN));}
?>
<div class="flex flex-col lg:flex-row lg:items-center justify-between gap-3 mb-6"><div><div class="text-xs tracking-[.2em] text-slate-400 font-black">CONTENT TYPE</div><h1 class="text-3xl font-black"><?=e(post_type_label($type))?></h1><div class="text-sm text-slate-500 mt-1">SEO URLs: /<?=e($type)?>/your-slug</div></div><a href="/admin/content-edit.php?type=<?=$type?>&id=0" class="grad600 shine text-white px-4 py-3 rounded-xl font-black">+ New <?=e(post_type_label($type))?></a></div>
