<div class="grid xl:grid-cols-[1fr_560px] gap-6">
<div class="bg-white border rounded-2xl overflow-hidden soft"><form method="post" onsubmit="return confirmBulk()"><div class="p-4 border-b flex flex-col xl:flex-row gap-2"><?=csrf_input()?><input type="hidden" name="action" value="bulk"><input id="contentSearch" oninput="filterRows()" placeholder="Search posts..." class="flex-1 rounded-xl border-slate-200"><select name="bulk_action" class="rounded-xl border-slate-200"><option value="">Bulk action</option><option value="publish">Publish</option><option value="draft">Move to Draft</option><option value="private">Set Private</option><option value="delete">Delete</option><option value="category:clear">Remove Category</option><?php foreach($cats as $c):?><option value="category:assign:<?=$c['id']?>">Assign Category: <?=e($c['name'])?></option><?php endforeach;?><option value="tags:clear">Remove All Tags</option><?php foreach($tags as $t):?><option value="tag:add:<?=$t['id']?>">Add Tag: <?=e($t['name'])?></option><option value="tag:remove:<?=$t['id']?>">Remove Tag: <?=e($t['name'])?></option><?php endforeach;?></select><button class="rounded-xl bg-slate-950 text-white px-4 font-bold">Apply</button></div><div class="overflow-x-auto"><table class="w-full text-sm" id="contentTable"><thead class="bg-slate-50"><tr><th class="p-3"><input type="checkbox" onclick="document.querySelectorAll('.rowcheck').forEach(x=>x.checked=this.checked)"></th><th class="p-3 text-left">Title</th><th class="p-3 text-left">Category</th><th class="p-3 text-left">Status</th><th class="p-3 text-right">Action</th></tr></thead><tbody><?php foreach($posts as $r):?><tr class="border-t content-row"><td class="p-3"><input class="rowcheck" type="checkbox" name="ids[]" value="<?=$r['id']?>"></td><td class="p-3"><div class="font-bold post-title"><?=e($r['title'])?></div><div class="text-xs text-slate-400">/<?=e($type)?>/<?=e($r['slug'])?></div></td><td class="p-3"><?=e($r['category_name']??'—')?></td><td class="p-3"><span class="px-2 py-1 rounded-full text-xs font-bold <?=($r['status']==='publish'?'bg-emerald-100 text-emerald-700':($r['status']==='private'?'bg-purple-100 text-purple-700':'bg-amber-100 text-amber-700'))?>"><?=e($r['status'])?></span></td><td class="p-3 text-right"><a href="/admin/content-edit.php?type=<?=$type?>&id=<?=$r['id']?>" class="text-blue-600 font-black">Edit</a><a href="<?=content_url($type,$r['slug'])?>" target="_blank" class="ml-3 font-bold">View</a></td></tr><?php endforeach;?></tbody></table></div></form></div>
<div id="editor" class="bg-white border rounded-2xl p-5 soft"><div class="font-black text-lg"><?=($form['id']?'Edit':'Create')?> <?=e(post_type_label($type))?></div><form method="post" enctype="multipart/form-data" class="mt-4 space-y-3"><?=csrf_input()?><input type="hidden" name="action" value="save"><input type="hidden" name="id" value="<?=e((string)$form['id'])?>"><input required name="title" value="<?=e($form['title'])?>" placeholder="Title" class="w-full rounded-xl border-slate-200"><input name="slug" value="<?=e($form['slug'])?>" placeholder="SEO slug" class="w-full rounded-xl border-slate-200"><textarea name="excerpt" placeholder="Short excerpt" class="w-full rounded-xl border-slate-200 min-h-20"><?=e($form['excerpt'])?></textarea><label class="text-xs font-bold text-slate-500">Content Editor</label><?php require __DIR__.'/rich_editor.php';rich_editor('content',(string)$form['content'],'contentEditor');?>
<div class="grid grid-cols-2 gap-2"><select name="status" class="rounded-xl border-slate-200"><option value="draft" <?=$form['status']==='draft'?'selected':''?>>Draft</option><option value="publish" <?=$form['status']==='publish'?'selected':''?>>Publish</option><option value="private" <?=$form['status']==='private'?'selected':''?>>Private</option></select><select name="visibility" class="rounded-xl border-slate-200"><option value="public" <?=$form['visibility']==='public'?'selected':''?>>Public</option><option value="members" <?=$form['visibility']==='members'?'selected':''?>>Members only</option></select></div><select name="category_id" class="w-full rounded-xl border-slate-200"><option value="">Category</option><?php foreach($cats as $c):?><option value="<?=$c['id']?>" <?=$form['category_id']==$c['id']?'selected':''?>><?=e($c['name'])?></option><?php endforeach;?></select><div><label class="text-xs font-bold text-slate-500">Cover image — choose file</label><input type="file" name="cover_file" accept="image/*" class="mt-1 w-full rounded-xl border p-3 bg-white"><input type="hidden" name="existing_cover" value="<?=e($form['cover_image'])?>"></div><?php if($form['cover_image']):?><img src="<?=e($form['cover_image'])?>" class="w-full h-32 object-cover rounded-xl border"><?php endif;?><div><div class="text-xs font-bold text-slate-500 mb-2">Tags</div><div class="flex flex-wrap gap-2 max-h-32 overflow-auto"><?php foreach($tags as $t):?><label class="flex items-center gap-2 text-xs bg-slate-50 px-3 py-2 rounded-xl"><input type="checkbox" name="tags[]" value="<?=$t['id']?>" <?=in_array((int)$t['id'],$selectedTags,true)?'checked':''?>><?=e($t['name'])?></label><?php endforeach;?></div></div><div class="grid grid-cols-2 gap-2"><input name="seo_title" value="<?=e($form['seo_title'])?>" placeholder="SEO title" class="rounded-xl border-slate-200"><input name="seo_keywords" value="<?=e($form['seo_keywords'])?>" placeholder="SEO keywords" class="rounded-xl border-slate-200"><textarea name="seo_description" placeholder="Meta description" class="rounded-xl border-slate-200 min-h-20 col-span-2"><?=e($form['seo_description'])?></textarea><select name="schema_type" class="rounded-xl border-slate-200 col-span-2"><option <?=($form['schema_type']==='Article'?'selected':'')?>>Article</option><option <?=($form['schema_type']==='WebPage'?'selected':'')?>>WebPage</option><option <?=($form['schema_type']==='TechArticle'?'selected':'')?>>TechArticle</option><option <?=($form['schema_type']==='FAQPage'?'selected':'')?>>FAQPage</option></select></div><label class="flex items-center gap-2 text-sm"><input type="checkbox" name="featured" <?=$form['featured']?'checked':''?>> Featured</label><button class="shine grad600 text-white w-full py-3 rounded-xl font-black">Save <?=e(post_type_label($type))?></button></form></div></div>
<script>function filterRows(){const q=(document.getElementById('contentSearch').value||'').toLowerCase();document.querySelectorAll('.content-row').forEach(r=>r.style.display=r.innerText.toLowerCase().includes(q)?'':'none')}function confirmBulk(){const checked=document.querySelectorAll('.rowcheck:checked').length;const a=document.querySelector('select[name=bulk_action]').value;if(!checked){alert('Select at least one post.');return false}if(a==='delete'&& !confirm('Delete selected posts? This cannot be undone.'))return false;return true}</script>
